column19:
-- Chiều thời gian theo ngày
SELECT TRUNC(min_ngay) + LEVEL - 1 AS ngay
FROM (
    SELECT LEAST(
        NVL((SELECT MIN(BUSINESS_LICENSE_DATE) FROM SCMS_UAT.SC_FIRM_INFO WHERE BUSINESS_LICENSE_DATE IS NOT NULL), SYSDATE),
        NVL((SELECT MIN(END_DATE) FROM SCMS_UAT.SC_FIRM_PERIODIC_REPORT WHERE END_DATE IS NOT NULL), SYSDATE)
    ) AS min_ngay FROM DUAL
)
CONNECT BY TRUNC(min_ngay) + LEVEL - 1 <= TRUNC(SYSDATE)
ORDER BY ngay;

-- Chiều thời gian theo ngày
SELECT TRUNC(min_ngay) + LEVEL - 1 AS ngay
FROM (
    SELECT LEAST(
        NVL((SELECT MIN(WORK_START_DATE) FROM SCMS_UAT.SC_FIRM_SENIOR_PERSONNEL WHERE WORK_START_DATE IS NOT NULL), SYSDATE),
        NVL((SELECT MIN(SENT_AT) FROM SCMS_UAT.SC_FIRM_PERIODIC_REPORT WHERE SENT_AT IS NOT NULL), SYSDATE)
    ) AS min_ngay FROM DUAL
)
CONNECT BY TRUNC(min_ngay) + LEVEL - 1 <= TRUNC(SYSDATE)
ORDER BY ngay;

-- Chiều thời gian theo ngày
SELECT TRUNC(min_ngay) + LEVEL - 1 AS ngay
FROM (
    SELECT LEAST(
        NVL((SELECT MIN(SENT_AT) FROM SCMS_UAT.SC_FIRM_PERIODIC_REPORT WHERE SENT_AT IS NOT NULL), SYSDATE),
        NVL((SELECT MIN(SENT_AT) FROM SCMS_UAT.SC_FIRM_ADHOC_REPORT WHERE SENT_AT IS NOT NULL), SYSDATE)
    ) AS min_ngay FROM DUAL
)
CONNECT BY TRUNC(min_ngay) + LEVEL - 1 <= TRUNC(SYSDATE)
ORDER BY ngay;
